package com.bank.dr.model;

// Each pattern with its TYPICAL achievable RTO/RPO (minutes) and relative cost (1=cheapest).
public enum DrPattern {
    BACKUP_AND_RESTORE(480, 60, 1),   // hours to recover, backup-interval data loss
    PILOT_LIGHT(60, 5, 2),            // core replicated, compute started on failover
    WARM_STANDBY(10, 1, 3),           // scaled-down live stack, fast failover
    MULTI_SITE_ACTIVE_ACTIVE(1, 0, 4);// full dual-region, near-zero downtime/loss

    private final int typicalRtoMinutes;
    private final int typicalRpoMinutes;
    private final int costRank;

    DrPattern(int rto, int rpo, int costRank) {
        this.typicalRtoMinutes = rto;
        this.typicalRpoMinutes = rpo;
        this.costRank = costRank;
    }

    public int getTypicalRtoMinutes() { return typicalRtoMinutes; }
    public int getTypicalRpoMinutes() { return typicalRpoMinutes; }
    public int getCostRank() { return costRank; }

    // Can this pattern meet the given targets?
    public boolean meets(int targetRto, int targetRpo) {
        return typicalRtoMinutes <= targetRto && typicalRpoMinutes <= targetRpo;
    }
}
