package com.bank.dr.model;

// Business-set targets for a workload.
public class RecoveryObjective {
    private final String workload;
    private final int rtoMinutes;   // max downtime
    private final int rpoMinutes;   // max data loss

    public RecoveryObjective(String workload, int rtoMinutes, int rpoMinutes) {
        this.workload = workload;
        this.rtoMinutes = rtoMinutes;
        this.rpoMinutes = rpoMinutes;
    }

    public String getWorkload() { return workload; }
    public int getRtoMinutes() { return rtoMinutes; }
    public int getRpoMinutes() { return rpoMinutes; }
}
