package com.bank.dr.select;

import com.bank.dr.model.DrPattern;
import com.bank.dr.model.RecoveryObjective;
import java.util.Arrays;
import java.util.Comparator;
import java.util.logging.Logger;

// Picks the CHEAPEST pattern that still meets the business targets.
public class DrPatternSelector {
    private static final Logger log = Logger.getLogger(DrPatternSelector.class.getName());

    public DrPattern selectFor(RecoveryObjective obj) {
        DrPattern chosen = Arrays.stream(DrPattern.values())
                .filter(p -> p.meets(obj.getRtoMinutes(), obj.getRpoMinutes()))
                .min(Comparator.comparingInt(DrPattern::getCostRank))   // cheapest that qualifies
                .orElseThrow(() -> new IllegalStateException(
                        "No pattern meets targets for " + obj.getWorkload()));

        log.info(() -> "[" + obj.getWorkload() + "] targets RTO<=" + obj.getRtoMinutes()
                + "m RPO<=" + obj.getRpoMinutes() + "m → choose " + chosen
                + " (cost rank " + chosen.getCostRank() + ")");
        return chosen;
    }
}
