package com.bank.dr.validate;

import com.bank.dr.model.RecoveryObjective;
import java.util.logging.Logger;

// Compares a SIMULATED actual recovery to the target — the "test, do not just document" step.
public class GameDayValidator {
    private static final Logger log = Logger.getLogger(GameDayValidator.class.getName());

    // true = game-day met targets; false = documented plan failed in reality.
    public boolean validate(RecoveryObjective obj, int actualRtoMinutes, int actualRpoMinutes) {
        boolean rtoOk = actualRtoMinutes <= obj.getRtoMinutes();
        boolean rpoOk = actualRpoMinutes <= obj.getRpoMinutes();

        if (rtoOk && rpoOk) {
            log.info(() -> "GAME-DAY PASS [" + obj.getWorkload() + "] actual RTO="
                    + actualRtoMinutes + "m RPO=" + actualRpoMinutes + "m within target");
            return true;
        }
        log.severe(() -> "GAME-DAY FAIL [" + obj.getWorkload() + "] actual RTO="
                + actualRtoMinutes + "m (target " + obj.getRtoMinutes() + "m), actual RPO="
                + actualRpoMinutes + "m (target " + obj.getRpoMinutes()
                + "m) — documented plan breached reality");
        return false;
    }
}
