package com.bank.dr;

import com.bank.dr.model.RecoveryObjective;
import com.bank.dr.select.DrPatternSelector;
import com.bank.dr.validate.GameDayValidator;
import java.util.logging.Logger;

// Runnable demo: three workloads + one failed game-day.
public class DrApplication {
    private static final Logger log = Logger.getLogger(DrApplication.class.getName());

    public static void main(String[] args) {
        DrPatternSelector selector = new DrPatternSelector();
        GameDayValidator validator = new GameDayValidator();

        log.info("=== National Bank of India — DR planning ===");

        // Problem 1: payments ledger — strict targets → active/active (or warm standby).
        RecoveryObjective ledger = new RecoveryObjective("payments-ledger", 5, 0);
        selector.selectFor(ledger);

        // Problem 2: interest batch — generous targets → cheap backup-and-restore.
        RecoveryObjective batch = new RecoveryObjective("interest-batch", 480, 60);
        selector.selectFor(batch);

        // Problem 3: statements portal — moderate targets → warm standby.
        RecoveryObjective portal = new RecoveryObjective("statements-portal", 30, 1);
        selector.selectFor(portal);

        // Problem 4: documented 10m RTO, but game-day reveals 40m due to manual DNS step.
        RecoveryObjective ledgerDocumented = new RecoveryObjective("payments-ledger", 10, 0);
        validator.validate(ledgerDocumented, 40, 0);  // actual RTO 40m breaches 10m target
    }
}
